/**
 * Async Deep Analysis System
 * 
 * Provides non-blocking deep compute for the Dynamics runtime.
 * When deep analysis is triggered, it runs in the background while
 * the fast path returns immediately.
 * 
 * Key features:
 * - Non-blocking deep analysis
 * - Result caching for session enrichment
 * - Event-driven updates
 * - Latency budget enforcement
 */

// Governed: routed through invokeLLM governance pipeline
import { governedClaude } from '../../governance/governed-anthropic';
import { EventEmitter } from 'events';
import { EmotionalState } from './runtime';
import { thinkingCache } from './thinking-cache';
import { extractJSON } from '../utils/json-parser';
import { generalLog } from '../../_core/logger';
import { MODELS } from "../../_core/models";

// ============================================================================
// TYPES
// ============================================================================

export interface DeepAnalysisRequest {
  requestId: string;
  sessionId: string;
  message: string;
  currentState: EmotionalState;
  triggerReason: string;
  timestamp: number;
}

export interface DeepAnalysisResult {
  requestId: string;
  sessionId: string;
  enrichedState: Partial<EmotionalState>;
  thinking: string;
  insights: DeepInsights;
  latencyMs: number;
  timestamp: number;
}

export interface DeepInsights {
  attractorAnalysis: {
    currentAttractor: string;
    attractorDepth: number;
    escapeVelocity: number;
    likelyTrajectory: string;
  };
  orbitDetection: {
    isOrbiting: boolean;
    orbitPattern?: string;
    cycleLength?: number;
    breakoutProbability: number;
  };
  riskAssessment: {
    escalationRisk: number;
    ruptureRisk: number;
    repairOpportunity: number;
    interventionUrgency: 'low' | 'medium' | 'high' | 'critical';
  };
  recommendations: string[];
}

export type DeepAnalysisStatus = 'pending' | 'running' | 'completed' | 'failed';

interface PendingAnalysis {
  request: DeepAnalysisRequest;
  status: DeepAnalysisStatus;
  result?: DeepAnalysisResult;
  error?: string;
  startTime?: number;
}

// ============================================================================
// ASYNC DEEP ANALYSIS MANAGER
// ============================================================================

class AsyncDeepAnalysisManager extends EventEmitter {
  private pending: Map<string, PendingAnalysis> = new Map();
  private completed: Map<string, DeepAnalysisResult> = new Map();
  private anthropic: typeof governedClaude;
  private maxConcurrent: number = 5;
  private currentRunning: number = 0;
  private queue: DeepAnalysisRequest[] = [];
  private latencyBudgetMs: number = 10000; // 10 second max

  constructor() {
    super();
    this.anthropic = governedClaude;
  }

  /**
   * Queue a deep analysis request (non-blocking)
   */
  queueAnalysis(request: DeepAnalysisRequest): void {
    this.pending.set(request.requestId, {
      request,
      status: 'pending',
    });

    this.queue.push(request);
    this.emit('queued', request.requestId);

    // Process queue
    this.processQueue();
  }

  /**
   * Process the queue
   */
  private async processQueue(): Promise<void> {
    while (this.queue.length > 0 && this.currentRunning < this.maxConcurrent) {
      const request = this.queue.shift();
      if (request) {
        this.runAnalysis(request);
      }
    }
  }

  /**
   * Run a single deep analysis
   */
  private async runAnalysis(request: DeepAnalysisRequest): Promise<void> {
    const pending = this.pending.get(request.requestId);
    if (!pending) return;

    pending.status = 'running';
    pending.startTime = Date.now();
    this.currentRunning++;
    this.emit('started', request.requestId);

    try {
      const result = await this.executeDeepAnalysis(request);

      pending.status = 'completed';
      pending.result = result;

      // Store in completed cache
      this.completed.set(request.sessionId, result);

      // Cache thinking for future use
      thinkingCache.set(
        request.currentState.regime,
        request.currentState.threat,
        request.currentState.acceleration,
        result.thinking,
        result.enrichedState.confidence || 0.9
      );

      this.emit('completed', request.requestId, result);
    } catch (error) {
      pending.status = 'failed';
      pending.error = error instanceof Error ? error.message : 'Unknown error';
      this.emit('failed', request.requestId, pending.error);
    } finally {
      this.currentRunning--;
      this.processQueue();
    }
  }

  /**
   * Execute the actual deep analysis with Claude
   */
  private async executeDeepAnalysis(request: DeepAnalysisRequest): Promise<DeepAnalysisResult> {
    const startTime = Date.now();

    const response = await this.anthropic.messages.create({
      model: MODELS.generation,
      max_tokens: 4096,
      thinking: {
        type: 'enabled',
        budget_tokens: 3072,
      },
      messages: [{
        role: 'user',
        content: `DEEP EMOTIONAL DYNAMICS ANALYSIS

Trigger: ${request.triggerReason}

Current Emotional State:
${JSON.stringify(request.currentState, null, 2)}

User Message: "${request.message}"

Perform comprehensive analysis:

1. ATTRACTOR ANALYSIS
- What emotional attractor is the person currently in?
- How deep are they in this attractor (escape difficulty)?
- What would the escape velocity be (energy needed to shift)?
- What's the likely trajectory if no intervention?

2. ORBIT DETECTION
- Is there a cycling pattern (approach-withdraw, idealize-devalue)?
- What's the orbit pattern if detected?
- How many turns in the cycle?
- What's the probability of breaking out?

3. RISK ASSESSMENT
- Escalation risk (0-1)
- Rupture risk (0-1)
- Repair opportunity (0-1)
- Intervention urgency (low/medium/high/critical)

4. ENRICHED STATE
Update the emotional state with refined values based on deep analysis.

5. RECOMMENDATIONS
What specific interventions would help?

Return as JSON:
{
  "enrichedState": {
    "mass": <refined>,
    "distance": <refined>,
    "charge": <refined>,
    "threat": <refined>,
    "momentum": <refined>,
    "acceleration": <refined>,
    "fixation": <refined>,
    "orbit": <refined>,
    "regime": <refined>,
    "confidence": <should be higher>
  },
  "insights": {
    "attractorAnalysis": {
      "currentAttractor": "<name>",
      "attractorDepth": <0-1>,
      "escapeVelocity": <0-1>,
      "likelyTrajectory": "<description>"
    },
    "orbitDetection": {
      "isOrbiting": <boolean>,
      "orbitPattern": "<pattern if orbiting>",
      "cycleLength": <turns if orbiting>,
      "breakoutProbability": <0-1>
    },
    "riskAssessment": {
      "escalationRisk": <0-1>,
      "ruptureRisk": <0-1>,
      "repairOpportunity": <0-1>,
      "interventionUrgency": "<low|medium|high|critical>"
    },
    "recommendations": ["<recommendation 1>", "<recommendation 2>", ...]
  }
}`
      }]
    });

    let thinking = '';
    let text = '';

    for (const block of response.content) {
      if ((block as unknown as Record<string, unknown>).type === 'thinking') {
        thinking = (block as unknown as Record<string, unknown>).thinking;
      } else if (block.type === 'text') {
        text = block.text;
      }
    }

    const parsed = extractJSON(text, { enrichedState: {}, insights: null } as { enrichedState: Partial<EmotionalState>; insights: DeepInsights | null });
    const latencyMs = Date.now() - startTime;

    // Enforce latency budget
    if (latencyMs > this.latencyBudgetMs) {
      generalLog.warn(`[AsyncDeep] Analysis exceeded latency budget: ${latencyMs}ms > ${this.latencyBudgetMs}ms`);
    }

    return {
      requestId: request.requestId,
      sessionId: request.sessionId,
      enrichedState: parsed?.enrichedState || {},
      thinking,
      insights: parsed?.insights || {
        attractorAnalysis: {
          currentAttractor: 'unknown',
          attractorDepth: 0.5,
          escapeVelocity: 0.5,
          likelyTrajectory: 'uncertain',
        },
        orbitDetection: {
          isOrbiting: false,
          breakoutProbability: 0.5,
        },
        riskAssessment: {
          escalationRisk: 0.5,
          ruptureRisk: 0.3,
          repairOpportunity: 0.5,
          interventionUrgency: 'medium',
        },
        recommendations: [],
      },
      latencyMs,
      timestamp: Date.now(),
    };
  }

  /**
   * Get the latest completed result for a session
   */
  getLatestResult(sessionId: string): DeepAnalysisResult | null {
    return this.completed.get(sessionId) || null;
  }

  /**
   * Get status of a pending analysis
   */
  getStatus(requestId: string): PendingAnalysis | null {
    return this.pending.get(requestId) || null;
  }

  /**
   * Wait for a specific analysis to complete (with timeout)
   */
  async waitForResult(requestId: string, timeoutMs: number = 15000): Promise<DeepAnalysisResult | null> {
    const pending = this.pending.get(requestId);
    if (!pending) return null;

    if (pending.status === 'completed' && pending.result) {
      return pending.result;
    }

    return new Promise((resolve) => {
      const timeout = setTimeout(() => {
        this.removeListener('completed', onComplete);
        this.removeListener('failed', onFailed);
        resolve(null);
      }, timeoutMs);

      const onComplete = (completedId: string, result: DeepAnalysisResult) => {
        if (completedId === requestId) {
          clearTimeout(timeout);
          this.removeListener('completed', onComplete);
          this.removeListener('failed', onFailed);
          resolve(result);
        }
      };

      const onFailed = (failedId: string) => {
        if (failedId === requestId) {
          clearTimeout(timeout);
          this.removeListener('completed', onComplete);
          this.removeListener('failed', onFailed);
          resolve(null);
        }
      };

      this.on('completed', onComplete);
      this.on('failed', onFailed);
    });
  }

  /**
   * Get queue stats
   */
  getStats(): {
    queueLength: number;
    running: number;
    completed: number;
    pending: number;
  } {
    let pendingCount = 0;
    let completedCount = 0;

    for (const p of this.pending.values()) {
      if (p.status === 'pending') pendingCount++;
      if (p.status === 'completed') completedCount++;
    }

    return {
      queueLength: this.queue.length,
      running: this.currentRunning,
      completed: completedCount,
      pending: pendingCount,
    };
  }

  /**
   * Clear old completed results
   */
  cleanup(maxAge: number = 3600000): void {
    const now = Date.now();

    for (const [sessionId, result] of this.completed.entries()) {
      if (now - result.timestamp > maxAge) {
        this.completed.delete(sessionId);
      }
    }

    for (const [requestId, pending] of this.pending.entries()) {
      if (pending.result && now - pending.result.timestamp > maxAge) {
        this.pending.delete(requestId);
      }
    }
  }
}

// ============================================================================
// SINGLETON INSTANCE
// ============================================================================

export const asyncDeepManager = new AsyncDeepAnalysisManager();

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Generate a unique request ID
 */
export function generateRequestId(): string {
  return `deep_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Queue a deep analysis (convenience function)
 */
export function queueDeepAnalysis(
  sessionId: string,
  message: string,
  currentState: EmotionalState,
  triggerReason: string
): string {
  const requestId = generateRequestId();

  asyncDeepManager.queueAnalysis({
    requestId,
    sessionId,
    message,
    currentState,
    triggerReason,
    timestamp: Date.now(),
  });

  return requestId;
}

/**
 * Get latest deep insights for a session
 */
export function getDeepInsights(sessionId: string): DeepInsights | null {
  const result = asyncDeepManager.getLatestResult(sessionId);
  return result?.insights || null;
}

export default asyncDeepManager;

