// Governed: routed through invokeLLM governance pipeline
import { governedClaude } from '../../governance/governed-anthropic';
import { EventEmitter } from 'events';
import { EmotionalState } from './runtime';
import { thinkingCache } from './thinking-cache';
import { extractJSON } from '../utils/json-parser';
import { generalLog } from '../../_core/logger';
import { MODELS } from "../../_core/models";

// ============================================================================
// TYPES
// ============================================================================

export interface DeepAnalysisRequest {
  requestId: string;
  sessionId: string;
  message: string;
  currentState: EmotionalState;
  triggerReason: string;
  timestamp: number;
}

