    orbitPattern?: string;
    cycleLength?: number;
    breakoutProbability: number;
  };
  riskAssessment: {
    escalationRisk: number;
    ruptureRisk: number;
    repairOpportunity: number;
    interventionUrgency: 'low' | 'medium' | 'high' | 'critical';
  };
  recommendations: string[];
}

