      const result = await this.executeDeepAnalysis(request);

      pending.status = 'completed';
      pending.result = result;

      // Store in completed cache
      this.completed.set(request.sessionId, result);

      // Cache thinking for future use
      thinkingCache.set(
        request.currentState.regime,
        request.currentState.threat,
        request.currentState.acceleration,
        result.thinking,
        result.enrichedState.confidence || 0.9
      );

