    } catch (error) {
      pending.status = 'failed';
      pending.error = error instanceof Error ? error.message : 'Unknown error';
      this.emit('failed', request.requestId, pending.error);
    } finally {
      this.currentRunning--;
      this.processQueue();
    }
  }

  /**
   * Execute the actual deep analysis with Claude
   */
  private async executeDeepAnalysis(request: DeepAnalysisRequest): Promise<DeepAnalysisResult> {
    const startTime = Date.now();

    const response = await this.anthropic.messages.create({
      model: MODELS.generation,
      max_tokens: 4096,
      thinking: {
        type: 'enabled',
