    "threat": <refined>,
    "momentum": <refined>,
    "acceleration": <refined>,
    "fixation": <refined>,
    "orbit": <refined>,
    "regime": <refined>,
    "confidence": <should be higher>
  },
  "insights": {
    "attractorAnalysis": {
      "currentAttractor": "<name>",
      "attractorDepth": <0-1>,
      "escapeVelocity": <0-1>,
      "likelyTrajectory": "<description>"
    },
    "orbitDetection": {
      "isOrbiting": <boolean>,
      "orbitPattern": "<pattern if orbiting>",
      "cycleLength": <turns if orbiting>,
      "breakoutProbability": <0-1>
    },
    "riskAssessment": {
      "escalationRisk": <0-1>,
      "ruptureRisk": <0-1>,
      "repairOpportunity": <0-1>,
      "interventionUrgency": "<low|medium|high|critical>"
    },
    "recommendations": ["<recommendation 1>", "<recommendation 2>", ...]
  }
