  const requestId = generateRequestId();

  asyncDeepManager.queueAnalysis({
    requestId,
    sessionId,
    message,
    currentState,
    triggerReason,
    timestamp: Date.now(),
  });

  return requestId;
}

/**
 * Get latest deep insights for a session
 */
export function getDeepInsights(sessionId: string): DeepInsights | null {
  const result = asyncDeepManager.getLatestResult(sessionId);
  return result?.insights || null;
}

export default asyncDeepManager;

